"""``docs/READINESS.md``: the scorecards of all parliaments on one page.

Rendered from the scorecard files alone, so the page can be checked against them without any data repository.
"""

from __future__ import annotations

import json
from pathlib import Path

from . import config as cfg
from .criteria import CATALOGUE, SATISFIED

HEADER = """# Readiness of the parliaments

<!-- Generated by `python -m optv.scripts.readiness check`. Edit the criteria or the manifests, not this file. -->

Every parliament implemented in this repository, the level its implementation and data have reached, and what keeps it from the next one. The figures behind each line are in `docs/readiness/<CODE>.json`.
"""

LEVELS_SECTION = """## Levels

| Level | Name | Reached when |
|---|---|---|
| 1 | implemented | the parliament has a directory under `optv/parliaments/` |
| 2 | samples pass | its sample sessions satisfy every criterion gating level 2 |
| 3 | QC cleared | Whisper transcripts of the sample sessions confirm the text, and licence and platform fit are attested; the parliament is ready for a backfill and for going live |
| 4 | backfilled | the manifest declares the periods to be published as processed in full |
| 5 | live | the manifest declares a platform instance that serves the data |

Levels 2 and 3 are computed from the sample sessions named in the manifest. Levels 4 and 5 are declared there. A parliament at a declared level keeps it when a criterion below fails; the failure shows as a regression. Levels 1 to 4 are published as `in development`, level 5 as `production`.
"""


def load_scorecards(tools: Path | None = None) -> list[dict]:
    directory = cfg.readiness_dir(tools)
    if not directory.is_dir():
        return []
    cards = [json.loads(path.read_text()) for path in directory.glob("*.json")]
    return sorted(cards, key=lambda card: card["parliament"])


def _cell(text: str) -> str:
    return str(text).replace("|", "\\|").replace("\n", " ")


def _criteria_list(ids: list[str]) -> str:
    return ", ".join(f"`{cid}`" for cid in ids) if ids else "–"


def _figures(entry: dict) -> str:
    """The numbers of a result in a few words."""
    metrics = entry.get("metrics") or {}
    parts = []
    if "share" in metrics and "threshold" in metrics:
        parts.append(f"share {metrics['share']} against {metrics['threshold']}")
    elif "median_similarity" in metrics and "threshold" in metrics:
        parts.append(f"median similarity {metrics['median_similarity']} against {metrics['threshold']}")
    elif "leaks" in metrics:
        parts.append(f"{metrics['leaks']} of {metrics['text_speeches']} text speeches")
    if entry.get("detail"):
        parts.append(entry["detail"])
    return "; ".join(parts)


def _parliament_section(card: dict) -> list[str]:
    criteria = card.get("criteria") or {}
    satisfied = sum(1 for entry in criteria.values() if entry["status"] in SATISFIED)
    lines = [f"### {card['parliament']}: {card.get('name', '')}", ""]
    summary = (f"Level {card['level']} ({card['level_name']}), {card['status']}. "
               f"{satisfied} of {len(criteria)} criteria satisfied.")
    evaluated = card.get("evaluated") or {}
    if evaluated.get("date"):
        summary += f" Evaluated {evaluated['date']} at `{evaluated.get('tools', 'unknown')}`."
    lines += [summary, ""]
    samples = card.get("samples") or {}
    if samples:
        speeches = sum(s.get("speeches", 0) for s in samples.values())
        hours = sum(s.get("audio_seconds", 0) for s in samples.values()) / 3600
        lines += [f"Sample sessions: {', '.join(f'`{sid}`' for sid in samples)} "
                  f"({speeches} speeches, {hours:.1f} h of audio).", ""]
    open_entries = [(cid, entry) for cid, entry in criteria.items() if entry["status"] not in SATISFIED]
    if open_entries:
        lines += ["| Criterion | Gates level | Result | Detail |", "|---|---|---|---|"]
        for cid, entry in open_entries:
            lines.append(f"| `{cid}` | {entry['level']} | {entry['status']} | {_cell(_figures(entry))} |")
        lines.append("")
    return lines


def render(cards: list[dict]) -> str:
    cards = sorted(cards, key=lambda card: card["parliament"])
    lines = [HEADER, "## Overview", "",
             "| Parliament | Name | Level | Status | Blocks the next level | Regressions |",
             "|---|---|---|---|---|---|"]
    for card in cards:
        code = card["parliament"]
        lines.append(
            f"| [`{code}`](../optv/parliaments/{code}/) | {_cell(card.get('name', ''))} "
            f"| {card['level']} {card['level_name']} | {card['status']} "
            f"| {_criteria_list(card.get('blocking') or [])} "
            f"| {_criteria_list(card.get('regressions') or [])} |")
    lines += ["", LEVELS_SECTION, "## Criteria", "",
              "| Criterion | Gates level | Kind | Rule |", "|---|---|---|---|"]
    for criterion in CATALOGUE:
        lines.append(f"| `{criterion.id}` | {criterion.level} | {criterion.kind} | {_cell(criterion.rule)} |")
    lines += ["", "A result is `pass`, `fail`, `not_evaluated` (the evidence does not exist yet), `not_applicable` or `stale` (the evidence describes an earlier state of the data). Thresholds are the defaults in `optv/scripts/readiness/config.py` unless a manifest overrides one with a reason.",
              "", "## Open criteria per parliament", ""]
    for card in cards:
        lines += _parliament_section(card)
    return "\n".join(lines).rstrip("\n") + "\n"


def write(tools: Path | None = None) -> bool:
    """Render the page from the scorecards on disk. Returns whether the file changed."""
    path = cfg.overview_path(tools)
    text = render(load_scorecards(tools))
    if path.is_file() and path.read_text() == text:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text)
    return True


def is_current(tools: Path | None = None) -> bool:
    path = cfg.overview_path(tools)
    return path.is_file() and path.read_text() == render(load_scorecards(tools))
